// Master APS Production Schedule Data (Months 1 to 8: Jan - Aug 2026)
// System Assembly (CPU) Lines: C32, C22, C21, C31, TC11, TR11, C33, R01
// Fully integrated with IE Standard DL benchmarks per line & shift.

export interface ApsOrderItem {
  id: string;
  plant: string;
  area: string;
  dType: string;
  line: string;
  family: string;
  category: string;
  model: string;
  planQty: number;
  mo: string;
  sequence: string;
  dn: string;
  remark: string;
  uph: string;
  totalScheduledQty: number;
  activeDaysCount: number;
  dailySchedule: Record<
    string,
    {
      dQty: number;
      nQty: number;
      totalQty: number;
      hasDayShift: boolean;
      hasNightShift: boolean;
      shiftsActive: number;
    }
  >;
}

export interface ApsLineSummaryItem {
  plant: string;
  line: string;
  family: string;
  model: string;
  orderCount: number;
  totalPlanQty: number;
  totalScheduledQty: number;
  activeDaysCount: number;
  daily: Record<
    string,
    {
      totalQty: number;
      shiftsActive: number;
      hasDay: boolean;
      hasNight: boolean;
      dQty: number;
      nQty: number;
    }
  >;
}

export interface MonthApsData {
  month: number;
  dates: string[];
  lines: ApsLineSummaryItem[];
  orders: ApsOrderItem[];
  totalPlanUnits: number;
  workingDays: number;
}

